"""Build a self-contained Persian HTML report from explicitly recorded test evidence.
No provider calls or browser automation. Re-run after updating evidence.json.
"""
from pathlib import Path
import base64, html, json

ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'docs/reports/live-test'
e=json.loads((OUT/'evidence.json').read_text(encoding='utf-8-sig'))
esc=lambda x:html.escape(str(x))
def picture(p):
    return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
rows=''.join(f'<tr><td>{esc(t["name"])}</td><td><span class="badge {esc(t["status"])}">{esc(t["label"])}</span></td><td>{esc(t["detail"])}</td></tr>' for t in e['checks'])
timeline=''.join(f'<li><time dir="ltr">{esc(t["at"])}</time><strong>{esc(t["title"])}</strong><p>{esc(t["detail"])}</p></li>' for t in e['timeline'])
fixes=''.join(f'<article><small>اصلاح {i+1:02}</small><h3>{esc(t["title"])}</h3><p>{esc(t["detail"])}</p></article>' for i,t in enumerate(e['fixes']))
shots=''.join(f'<figure><img src="{picture(OUT/"frames"/s["file"])}" alt="{esc(s["caption"])}" loading="lazy"><figcaption>{esc(s["caption"])}</figcaption></figure>' for s in e.get('screenshots',[]) if (OUT/'frames'/s['file']).exists())
font=next((ROOT/'dist/assets').glob('*arabic*.woff2'),None)
fontcss=f'@font-face{{font-family:Vazir;src:url(data:font/woff2;base64,{base64.b64encode(font.read_bytes()).decode()}) format("woff2");font-weight:100 900}}' if font else ''
doc='''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>گزارش آزمون واقعی همراه و گل‌بازار</title><style>FONT
:root{--bg:#101819;--card:#192424;--line:#334441;--fg:#e6eeea;--muted:#a5b9b1;--jade:#88d5b1;--amber:#edc58f}*{box-sizing:border-box}body{margin:0;overflow-wrap:anywhere;background:var(--bg);color:var(--fg);font:16px/1.9 Vazir,Tahoma,sans-serif}a{color:var(--jade)}main{min-width:0;max-width:1120px;margin:auto;padding:35px 24px 80px}header{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:18px;color:var(--muted);font-size:13px}.hero{padding:62px 0 30px}.eyebrow{color:var(--jade);font-size:13px}h1{font-size:clamp(32px,5vw,58px);line-height:1.4;max-width:850px;margin:18px 0}h2{font-size:25px;margin:45px 0 22px}h3{font-size:18px}.lead{color:var(--muted);max-width:850px;font-size:18px}.notice{padding:24px;border:1px solid #776145;background:#29281f;border-radius:18px;color:var(--amber)}.metrics,.fixes{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.metric,article{padding:24px;border:1px solid var(--line);border-radius:18px;background:var(--card)}.metric strong{display:block;font-size:32px;color:var(--jade)}small,.metric span{color:var(--muted);font-size:13px}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:right;border-bottom:1px solid var(--line);padding:16px 12px;vertical-align:top}th{color:var(--muted)}.tablewrap{max-width:100%;overflow:auto;border:1px solid var(--line);border-radius:18px}.badge{display:inline-block;white-space:nowrap;border-radius:30px;padding:3px 12px;font-size:12px;background:#283d32;color:var(--jade)}.badge.blocked,.badge.partial{background:#3a3022;color:var(--amber)}.badge.failed{background:#492c2c;color:#f3b7aa}ol{list-style:none;padding:0}li{border-right:2px solid var(--line);padding:0 24px 20px;margin-right:8px}time{display:block;color:var(--muted);font-size:12px}li strong{font-size:18px}li p,article p{color:var(--muted)}pre{direction:ltr;text-align:left;background:#0d1213;border:1px solid var(--line);padding:22px;border-radius:16px;overflow:auto;font-size:12px}figure{margin:24px 0;background:var(--card);border:1px solid var(--line);border-radius:18px;overflow:hidden}img{width:100%;height:auto;display:block}figcaption{padding:15px;color:var(--muted);font-size:13px}video{width:100%;border-radius:18px;background:#000}.actions{display:flex;gap:20px;flex-wrap:wrap}button{font:inherit;padding:10px 20px;min-height:44px;color:#123627;background:var(--jade);border:0;border-radius:10px;cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid var(--amber);outline-offset:4px}footer{border-top:1px solid var(--line);padding-top:25px;color:var(--muted);font-size:12px}@media(max-width:700px){.metrics,.fixes{grid-template-columns:1fr}header{gap:20px}.hero{padding-top:30px}main{padding:20px 16px}th,td{padding:12px 8px;min-width:95px}}@media print{body{background:white;color:#172e24}main{max-width:none}.metric,article,figure{break-inside:avoid;background:white}video,button{display:none}.lead,li p,article p,small,figcaption{color:#43594c}a{color:#245f43}.tablewrap{overflow:visible}pre{white-space:pre-wrap;color:#203a2b;background:#f0f5f0}}</style></head><body><main><header><b>همراه<span style="color:var(--jade)">.</span> / گزارش آزمون</b><span>DATE · گل‌بازار / Liara + Cursor SDK</span></header><section class="hero"><div class="eyebrow">از سورس واقعی تا شواهد قابل پیگیری</div><h1>TITLE</h1><p class="lead">SUMMARY</p><p class="notice">NOTICE</p><div class="actions"><button onclick="window.print()">چاپ یا ذخیرهٔ PDF</button><a href="evidence.json" download>دریافت شواهد JSON</a><a href="walkthrough.mp4">ویدئوی مراحل</a></div></section><div class="metrics"><div class="metric"><strong>TESTCOUNT</strong><span>تست خودکار موفق</span></div><div class="metric"><strong>۲٬۰۸۳ تومان</strong><span>برآورد ساعتی برنامه و دیتابیس؛ پیش از هزینه‌های متغیر</span></div><div class="metric"><strong>CLEANUP</strong><span>وضعیت منابع آزمایشی ابری</span></div></div><h2>چه چیزهایی واقعاً بررسی شد؟</h2><div class="tablewrap"><table><thead><tr><th>بررسی</th><th>نتیجه</th><th>شاهد و محدودیت</th></tr></thead><tbody>ROWS</tbody></table></div><h2>مسیر آزمون با زمان ثبت‌شده</h2><ol>TIMELINE</ol><h2>اصلاحاتی که از آزمون به محصول برگشت</h2><div class="fixes">FIXES</div><h2>تصاویر واقعی مراحل</h2>SHOTS<h2>ویدئوی مرور مراحل</h2><p class="lead">این ویدئو از تصاویر واقعی ثبت‌شدهٔ مرورگر ساخته شده است؛ ضبط پیوستهٔ دسکتاپ یا ویدئوی صداگذاری‌شده نیست.</p><video controls preload="metadata" src="walkthrough.mp4"></video><h2>شناسه‌ها و نسخهٔ آزمایش‌شده</h2><pre>RECEIPT</pre><h2>محدودیت‌ها و کار باقی‌مانده</h2><p class="lead">LIMITATIONS</p><h2>مراجع فنی</h2><p><a href="https://github.com/liara-cloud/openapi">OpenAPI رسمی لیارا</a> · <a href="https://github.com/liara-cloud/cli">CLI رسمی لیارا</a> · <a href="https://liara.ir/landing/هاست-پایتون-python">توضیح رسمی هزینهٔ ساعتی</a></p><footer>گزارش محلی پروژهٔ همراه؛ کلیدهای دسترسی، رمز دیتابیس و مقادیر محیطی در این فایل وجود ندارند. تاریخ و وضعیت بر اساس شواهد ثبت‌شده است.</footer></main></body></html>'''
values={'FONT':fontcss,'DATE':esc(e['date']),'TITLE':esc(e['title']),'SUMMARY':esc(e['summary']),'NOTICE':esc(e['notice']),'TESTCOUNT':esc(e['testCount']),'CLEANUP':esc(e['cleanupLabel']),'ROWS':rows,'TIMELINE':timeline,'FIXES':fixes,'SHOTS':shots,'RECEIPT':esc(json.dumps(e['receipt'],ensure_ascii=False,indent=2)),'LIMITATIONS':esc(e['limitations'])}
for k,v in values.items():doc=doc.replace(k,v)
(OUT/'report.html').write_text(doc,encoding='utf-8')
print(OUT/'report.html')
